<?php
require_once __DIR__ . '/../includes/db.php';require_once __DIR__ . '/../includes/auth.php';requireLogin();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location: dashboard.php#my-cvs');exit;}
$stmt=$pdo->prepare('SELECT * FROM cvs WHERE id=? AND user_id=? LIMIT 1');$stmt->execute([$id,getCurrentUserId()]);$cv=$stmt->fetch();if(!$cv){http_response_code(404);exit('Không tìm thấy CV hoặc bạn không có quyền truy cập.');}
$data=json_decode($cv['data'],true)?:[];$p=$data['personal']??[];$edu=$data['education'][0]??[];$exp=$data['experience'][0]??[];
$fields=['title'=>$cv['title'],'full_name'=>$p['full_name']??'','job_title'=>$p['job_title']??'','email'=>$p['email']??'','phone'=>$p['phone']??'','address'=>$p['address']??'','objective'=>is_string($data['objective']??'')?($data['objective']??''):'','school'=>$edu['school']??'','major'=>$edu['major']??'','education_period'=>$edu['period']??'','company'=>$exp['company']??'','job'=>$exp['position']??'','work_period'=>$exp['period']??'','experience'=>$exp['description']??'','skills'=>is_array($data['skills']??null)?implode(', ',$data['skills']):($data['skills']??''),'languages'=>is_array($data['languages']??null)?implode(', ',$data['languages']):($data['languages']??'')];
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){foreach($fields as $key=>$v)$fields[$key]=trim((string)($_POST[$key]??''));if($fields['title']===''||$fields['full_name']==='')$error='Tên CV và họ tên là bắt buộc.';else{$data['personal']=['full_name'=>$fields['full_name'],'job_title'=>$fields['job_title'],'email'=>$fields['email'],'phone'=>$fields['phone'],'address'=>$fields['address']];$data['objective']=$fields['objective'];$data['education']=array_values(array_filter([['school'=>$fields['school'],'major'=>$fields['major'],'period'=>$fields['education_period']]],fn($x)=>implode('',$x)!==''));$data['experience']=array_values(array_filter([['company'=>$fields['company'],'position'=>$fields['job'],'period'=>$fields['work_period'],'description'=>$fields['experience']]],fn($x)=>implode('',$x)!==''));$data['skills']=array_values(array_filter(array_map('trim',explode(',',$fields['skills']))));$data['languages']=array_values(array_filter(array_map('trim',explode(',',$fields['languages']))));$stmt=$pdo->prepare('UPDATE cvs SET title=?,data=? WHERE id=? AND user_id=?');$stmt->execute([$fields['title'],json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$id,getCurrentUserId()]);setFlashMessage('success','Đã lưu chỉnh sửa CV.');header('Location: preview.php?id='.$id);exit;}}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
