 với AI</a><a href="cv-templates.php">▣ Mẫu CV</a><a href="account.php">♙ Tài khoản</a></nav><a class="logout" href="logout.php">↪ Đăng xuất</a></aside><main class="main"><div class="wrap"><h1>Chỉnh sửa CV</h1><p>Chỉnh sửa thông tin bên dưới, lưu lại rồi bạn vẫn có thể mở xem trước và sửa tiếp bất cứ lúc nào.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post"><div class="field"><label>Tên CV *</label><input name="title" required value="<?=e($fields['title'])?>"></div><div class="grid"><div class="field"><label>Họ và tên *</label><input name="full_name" required value="<?=e($fields['full_name'])?>"></div><div class="field"><label>Vị trí ứng tuyển</label><input name="job_title" value="<?=e($fields['job_title'])?>"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($fields['email'])?>"></div><div class="field"><label>Số điện thoại</label><input name="phone" value="<?=e($fields['phone'])?>"></div></div><div class="field"><label>Địa chỉ</label><input name="address" value="<?=e($fields['address'])?>"></div><div class="field"><label>Mục tiêu nghề nghiệp</label><textarea name="objective"><?=e($fields['objective'])?></textarea></div><h3>Học vấn</h3><div class="grid"><div class="field"><label>Trường học</label><input name="school" value="<?=e($fields['school'])?>"></div><div class="field"><label>Ngành học</label><input name="major" value="<?=e($fields['major'])?>"></div><div class="field"><label>Thời gian học</label><input name="education_period" value="<?=e($fields['education_period'])?>"></div></div><h3>Kinh nghiệm</h3><div class="grid"><div class="field"><label>Công ty</label><input name="company" value="<?=e($fields['company'])?>"></div><div class="field"><label>Vị trí</label><input name="job" value="<?=e($fields['job'])?>"></div><div class="field"><label>Thời gian</label><input name="work_period" value="<?=e($fields['work_period'])?>"></div></div><div class="field"><label>Mô tả kinh nghiệm</label><textarea name="experience"><?=e($fields['experience'])?></textarea></div><div class="field"><label>Kỹ năng (cách nhau dấu phẩy)</label><input name="skills" value="<?=e($fields['skills'])?>"></div><div class="field"><label>Ngôn ngữ</label><input name="languages" value="<?=e($fields['languages'])?>"></div><button class="btn" type="submit">Lưu chỉnh sửa</button> <a class="btn" style="background:#e9eaff;color:#5148d8" href="preview.php?id=<?=$id?>">Quay lại xem trước</a></form></div></main></body></html>
